"""Original Datum Lancer, separate lance/shield grips and six action guides."""
import json
from PIL import Image
import produce as p
UID='unit_brasshollow_whitegauge_datum_lancers'
B=p.ROOT/'art/animation/source/poses'/UID
IDENTITY=('Original WHITEGAUGE DATUM LANCER from supplied painting, fixed three-quarter tactical camera facing SCREEN RIGHT. One human-sized armored adult with exactly TWO arms, TWO black-gloved hands and TWO armored human legs. Enclosed ivory domed gauge helmet with thin red calibration lines, brass circular side fittings and a small red tassel, black neck cloth, ivory/red shoulder and shin plates, brass round knee caps, black/brass boots, long dark charcoal split coat with red inner skirt, brass belt pendulum weights, rear brass pressure tank and red hoses. Helmet stays closed with no exposed face or new eyes. ONE long calibrated melee LANCE, not a gun or magical staff: original tapered ivory spearhead with thin red stripe, small brass circular gauge immediately beneath it, full black shaft sleeves, ivory shaft bands with red calibration marks and brass couplers, and pointed brass butt. ONE small round ivory gauge SHIELD with brass rim and center boss and thin red markings. Anatomical RIGHT near hand, on SCREEN LEFT in ready, holds the middle of the lance; anatomical LEFT far hand/forearm, on SCREEN RIGHT in ready, carries the shield. Hands have separate jobs: the lance never transfers to the shield hand. Preserve complete lance shaft/tip/butt, shield size, closed helmet, armor, coat, tank, hoses and weights. Original painterly strategy game artwork, no live action or plastic materials. ')
PLATE=(' Entire backdrop stays uniform magenta RGB255,0,255. No floor, cast shadow, scenery, text, camera motion, cuts or zoom. Fixed anatomical boot ground plane y576, body anchored at x480. Lifted feet may move but planted contacts cannot slide. Keep lance tip/butt, shield, both hands and all boots inside generous canvas margins. No projectile, sparks, particles, muzzle flash, smoke, magic rings, beams, glow or new equipment. ')
def reference(index):
 f=dict(json.loads((B/'packing.json').read_bytes())['frames'][index]);f['source']=(B/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8;return f
def support_reference():
 image=p.SOURCE_DIR/'support_shield_salute_v1.png';im=Image.open(image)
 return dict(name='support_raised_original_shield',source=image.relative_to(p.ROOT).as_posix(),rects=[[0,0,im.width,im.height]],anchor=[700,1168],scale=.188,alpha_noise_cutoff=8)
def recipe(clip,references,guides,last,action,seed):
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=False)
 c=dict(unit_id=UID,clip=clip,canvas=[960,640],anchor=[480,576],scale=.5,key_rgb=[255,0,255],seed=seed,references=references,guides=guides,last=last,prompt=(IDENTITY+action+PLATE).strip(),tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 p.write(out/'config.json',c);p.prepare(out,c);p.verify(out,c);print('Prepared',clip,flush=True)
if __name__=='__main__':
 recipe('move',[reference(i) for i in [14,2,3,4,5]],[[24,1],[44,2],[70,3],[93,4]],0,'One complete reciprocal walking cycle IN PLACE. Alternate the original two armored legs through forward contact, loading, passing, opposite forward contact and opposite passing, then return to original ready. Near RIGHT leg is on lance side, far LEFT leg on shield side. Both hips, knees and boot ankles articulate. Coat tails and belt weights respond subtly. RIGHT hand carries the complete upright lance; LEFT arm keeps the shield beside its chest. Keep the long weapon vertical while walking, no thrust or firing. Two distinct legs and opposite planted support, no sliding, hopping or root travel. ',2026110401)
 recipe('attack',[reference(i) for i in [14,6,7]],[[26,1],[53,2],[88,1]],0,'One physical melee spear thrust and recovery. RIGHT lance hand draws the complete shaft back across shoulder to original horizontal windup, then extends the same arm once SCREEN RIGHT, stepping into one grounded forward lunge and reaching with the same original spear tip. LEFT shield arm remains in front of chest through the lunge, never touching the shaft. Keep the spear shaft one rigid complete object with unchanged length and gauge. Around frame53 is full extended physical contact; no firing or energy beam. Recover continuously through drawn-back windup to original upright lance ready. Exactly one thrust and one recovery, no repeated attack. ',2026110402)
 recipe('hit',[reference(i) for i in [14,10]],[[39,1]],0,'One clear impact recoil followed by recovery. Helmet and torso lean backward, knees flex, shoulders recoil; RIGHT hand retains the upright lance and LEFT arm retains the shield. Both original boots remain grounded while weight shifts backward. Recover continuously to original balanced upright ready. No falling, thrust, firing or repeated recoil. ',2026110403)
 recipe('defend',[reference(i) for i in [14,8]],[],1,'One dedicated defensive brace transition. Bend both knees into a low wide planted stance, raise the round LEFT shield in front of upper chest, tilt the complete RIGHT-held lance diagonally upward SCREEN RIGHT across body as in supplied guard. Elbows bend and body lowers coherently. End in compact shield-first original braced guard and hold the final second. Both hands keep their separate lance/shield jobs. No thrust, firing or return to ready. ',2026110404)
 recipe('cast',[reference(14),support_reference()],[[47,1],[77,1]],0,'One NONMAGICAL physical rally salute. Both boots stay planted. LEFT shield arm deliberately lifts the same small round gauge shield above and to SCREEN RIGHT of helmet, with elbow naturally bending and then extending. RIGHT hand maintains its middle grip on the original long near-vertical lance on SCREEN LEFT. Helmet nods upward as shield rises. Hold the raised shield briefly, then lower LEFT shield arm continuously to original ready. A distinct high shield salute, not aiming or thrusting; no spellcasting, free hand, extra arm or altered shield size. ',2026110405)
 recipe('death',[reference(i) for i in [14,11,12,13]],[[34,1],[68,2]],3,'One continuous grounded forward-to-side collapse. Both armored knees buckle, torso lowers onto knees, then tips forward and falls onto original side. RIGHT hand releases the complete lance as support is lost; lance falls flat intact in front of the body. LEFT arm and its original small shield descend with the body and settle naturally onto ground. Preserve exactly two arms and two legs, closed helmet, original boots, tank, coat and full rigid lance throughout. End in supplied motionless grounded original corpse with shield and complete spear resting flat; final second completely still. ',2026110406)
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[c+'_h3_v1' for c in ['move','attack','hit','defend','cast','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='Original enclosed gauge-armored lancer, all 22 source poses and 8 enlarged articulated idle phases personally inspected. Preserve accepted idle/map pixels and 240ms timing; six dedicated H3 actions require complete original RGB/RGBA, enlarged, native/reflected and runtime visual acceptance. Melee-only; no invented ranged action.')))
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,canvas=[960,640],ground_anchor=[480,576],output_scale=.5,ready_guide=reference(14),corpse_guide=reference(13),support_guide=support_reference(),reason='One original anatomical scale per painting divided by fixed extraction scale; anatomical boots/corpse ground contact, not dangling spear butt; no per-frame normalization.'))
